/* usip_opcodes.h - uSIP (MD32 family, VLIW packet variant) instruction forms.
 * GENERATED by tools/gen_usip_tables.py from isa/usip_isa.json - do not edit by hand.
 * Units are 16-bit big-endian halfwords; bit 15 of a unit closes the packet; an instruction is a head (bit 15 = 0) plus
 * 0, 1 or 2 tails that are NOT necessarily adjacent (heads first, tails round-robin): see README.md "uSIP mode". */
